// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testRegression_property() public {
        LogFile log = new LogFile();
        c.SetMinSum(0);
        c.SetLogFile(address(log));
        c.Initialized();
        vm.warp(1000);
        address actor = address(0x1234);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Put{value: 1 wei}(0);
        bool ok;
        try c.Collect(1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
